import type { AnyComponentFunction } from '@exactjs/core';
import { createCompiledComponentInputReceipt } from '@exactjs/core/runtime/component-operations';
import { render, unmount } from '@exactjs/dom/root';

/** Reads the physical target generated by a compiled fixture, without invoking an event. */
export function compiledTargetIdentity(component: AnyComponentFunction): string {
	const host = document.createElement('div');
	try {
		render(createCompiledComponentInputReceipt(component, {}), host);
		const id = host.querySelector('[data-exact-id]')?.getAttribute('data-exact-id');
		if (!id) throw new Error('Expected a compiler-generated replay target');
		return id;
	} finally {
		unmount(host);
	}
}
